#!/usr/bin/env python3
"""Génère le site statique. Python standard uniquement."""
from pathlib import Path
import html, json, re, unicodedata, math
from content import LESSONS, GLOSSARY
from labs import LABS
ROOT=Path(__file__).resolve().parents[1]
SITE=ROOT/'site'
ORIGIN='https://christophegauld.github.io/classer-la-folie'
BOOK='https://www.editions-hermann.fr/livre/classer-la-folie-christophe-gauld'
REPO='https://github.com/ChristopheGauld/classer-la-folie'
e=html.escape
def text(s):
 s=e(s)
 return re.sub(r'\[\[([^]|]+)\|([^]]+)\]\]',lambda m:f'<a class="term" data-term="{m[1]}" href="lexique.html#{m[1]}">{m[2]}</a>',s)
def slug(s):
 return re.sub('[^a-z0-9]+','-',unicodedata.normalize('NFKD',s).encode('ascii','ignore').decode().lower()).strip('-')
def quote(s,p,wide=False):
 return f'<blockquote class="quote {"quote-wide" if wide else ""}"><p>« {e(s)} »</p><cite>Christophe Gauld · <a href="livre.html#citations"><i>Classer la folie ?</i></a>, p. {p}</cite></blockquote>'
def icon(kind):
 paths={'temps':'M4 43C19 0 25 65 40 27S56 26 67 10 M4 56H67', 'reseaux':'M12 15L53 10L60 51L22 58Z M12 15L60 51M22 58L53 10', 'prediction':'M8 35C22 9 49 9 65 35C49 61 22 61 8 35Z M36 23A12 12 0 1 0 36 47A12 12 0 1 0 36 23', 'raisonnement':'M8 10H45V23H61V62H24V49H8Z M18 33H49M36 10V62'}
 p=paths[kind]
 circles='<circle cx="12" cy="15" r="4"/><circle cx="53" cy="10" r="4"/><circle cx="60" cy="51" r="4"/><circle cx="22" cy="58" r="4"/>' if kind=='reseaux' else ''
 return f'<svg class="lab-icon" viewBox="0 0 74 74" aria-hidden="true"><g fill="none" stroke="currentColor" stroke-width="1.3">{circles}<path d="{p}"/></g></svg>'
def bookobject():
 return '<div class="book-object" aria-label="Composition typographique inspirée du titre, ce n’est pas la couverture du livre"><span class="book-author">Christophe Gauld</span><div><h3>Classer<br>la folie ?</h3><p style="margin-top:20px">Une philosophie<br>de la psychiatrie<br>pour le soin</p></div><p>HERMANN · 2026</p></div>'
def header(current):
 nav=''.join(f'<a href="{href}"'+(' aria-current="page"' if current==name else '')+f'>{name}</a>' for name,href in [('Parcours','parcours.html'),('Explorer','explorer.html'),('Lexique','lexique.html'),('Le livre','livre.html')])
 return f'''<a class="skip" href="#contenu">Aller au contenu</a><header class="site-header"><div class="wrap header-inner"><a class="brand" href="index.html" aria-label="Classer la folie, accueil"><span>Classer la folie<small>Philosophie de la psychiatrie</small></span><span class="brand-mark">?</span></a><nav class="nav" id="main-nav" aria-label="Navigation principale">{nav}<button class="search-trigger" aria-label="Rechercher dans le site" title="Rechercher · Ctrl ou ⌘ K"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.5" aria-hidden="true"><circle cx="10" cy="10" r="6"/><path d="M14.5 14.5L21 21"/></svg></button></nav><button class="menu-toggle" aria-expanded="false" aria-controls="main-nav" aria-label="Ouvrir le menu">☰</button></div></header>'''
def footer():
 return f'''<footer class="footer"><div class="wrap footer-inner"><div><a href="index.html">Classer la folie ? · Christophe Gauld</a><br>Un parcours à partir de l’ouvrage paru chez Hermann en 2026</div><div class="footer-links"><a href="sources.html">Sources et lectures</a><a href="livre.html#methode">À propos du site</a><a href="{REPO}">GitHub ↗</a></div></div></footer><dialog class="dialog" id="search-dialog" aria-labelledby="search-title"><button class="dialog-close" aria-label="Fermer la recherche">×</button><h2 id="search-title">Chercher une idée</h2><label class="screenreader" for="site-search">Rechercher un concept ou une question</label><input class="search-field" id="site-search" type="search" placeholder="Symptôme, incertitude, réseaux…" autocomplete="off"><div id="search-status" class="small muted" aria-live="polite"></div><div class="search-results" id="search-results"></div></dialog><dialog class="dialog term-dialog" id="term-dialog" aria-labelledby="term-title"><button class="dialog-close" aria-label="Fermer la définition">×</button><span class="eyebrow">Un mot pour comprendre</span><h2 id="term-title"></h2><p id="term-definition"></p><a id="term-link" href="lexique.html">Retrouver dans le lexique →</a></dialog>'''
def page(filename,title,desc,body,current='',article=False):
 markup=f'''<!doctype html><html lang="fr"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width, initial-scale=1"><meta name="theme-color" content="#f6f3ec"><title>{e(title)} · Classer la folie ?</title><meta name="description" content="{e(desc,quote=True)}"><link rel="canonical" href="{ORIGIN}/{filename}"><meta property="og:type" content="{'article' if article else 'website'}"><meta property="og:title" content="{e(title,quote=True)}"><meta property="og:description" content="{e(desc,quote=True)}"><meta property="og:url" content="{ORIGIN}/{filename}"><meta property="og:locale" content="fr_FR"><meta name="author" content="Christophe Gauld"><link rel="icon" href="assets/favicon.svg" type="image/svg+xml"><link rel="preload" href="assets/literata.woff2" as="font" type="font/woff2" crossorigin><link rel="stylesheet" href="assets/style.css"><script src="assets/data.js" defer></script><script src="assets/app.js" defer></script></head><body>{header(current)}{'<div class="progress-strip" aria-hidden="true"><span id="reading-progress"></span></div>' if article else ''}{body}{footer()}</body></html>'''
 (SITE/filename).write_text(markup,encoding='utf-8')
