# Original SVG conceptual map, no external assets.
atlas='''<figure class="hero-figure"><div class="atlas"><svg viewBox="0 0 490 440" role="group" aria-labelledby="atlas-title atlas-description"><title id="atlas-title">Quatre questions autour de l’expérience vécue</title><desc id="atlas-description">Le temps, les relations, les attentes et le raisonnement forment quatre entrées vers les chapitres de la deuxième partie du livre.</desc><g fill="none" stroke="#c9cbb9" stroke-width=".8"><path d="M20 253C-25 120 152 54 270 66S491 174 477 314S259 437 137 402S34 319 20 253Z"/><path d="M42 253C2 139 159 79 270 89S467 184 451 308S260 412 150 380S57 315 42 253Z"/><path d="M65 251C29 155 166 104 268 112S443 195 426 301S262 387 164 357S80 310 65 251Z"/><path d="M88 250C58 174 173 129 265 136S419 207 400 295S265 362 180 334S104 306 88 250Z"/><path d="M111 248C86 195 180 155 262 161S393 218 375 290S267 338 194 312S127 300 111 248Z"/></g><g stroke="#a33e2c" stroke-width="1" fill="none"><path d="M245 223C190 180 120 160 100 126"/><path d="M245 223C285 162 357 159 383 125"/><path d="M245 223C295 274 357 293 380 336"/><path d="M245 223C197 272 133 295 107 337"/></g><circle cx="245" cy="223" r="77" fill="#f6f3ec" stroke="#a9b5a0"/><text class="serif" x="245" y="218" text-anchor="middle" font-size="24" fill="#244f48">Le symptôme</text><text x="245" y="242" text-anchor="middle" font-size="10" letter-spacing="1" fill="#626962">UNE EXPÉRIENCE VÉCUE</text><a href="temps.html" class="atlas-link"><circle cx="100" cy="126" r="6" fill="#a33e2c"/><text x="100" y="92" text-anchor="middle" class="serif" font-size="22" fill="#252b29">Le temps</text><text x="100" y="109" text-anchor="middle" font-size="10" fill="#626962">Comment cela évolue</text></a><a href="reseaux.html" class="atlas-link"><circle cx="383" cy="125" r="6" fill="#a33e2c"/><text x="383" y="91" text-anchor="middle" class="serif" font-size="22" fill="#252b29">Les relations</text><text x="383" y="108" text-anchor="middle" font-size="10" fill="#626962">Ce qui se relie</text></a><a href="prediction.html" class="atlas-link"><circle cx="380" cy="336" r="6" fill="#a33e2c"/><text x="380" y="367" text-anchor="middle" class="serif" font-size="22" fill="#252b29">Les attentes</text><text x="380" y="385" text-anchor="middle" font-size="10" fill="#626962">Ce qui forme l’expérience</text></a><a href="raisonnement.html" class="atlas-link"><circle cx="107" cy="337" r="6" fill="#a33e2c"/><text x="107" y="367" text-anchor="middle" class="serif" font-size="22" fill="#252b29">Le raisonnement</text><text x="107" y="385" text-anchor="middle" font-size="10" fill="#626962">Comment on comprend</text></a></svg><figcaption>Quatre entrées dans la deuxième partie de l’ouvrage</figcaption></div></figure>'''
labdescs=[('temps','Suivre les transformations','Une vallée, une crête, une bille : comprendre pourquoi un même changement peut avoir des effets différents.'),('reseaux','Lire les relations','Distinguer une association, une influence supposée et le lien tel qu’une personne le perçoit.'),('prediction','Explorer les attentes','Observer comment une information modifie une estimation, selon l’attente de départ et la fiabilité supposée de l’indice.'),('raisonnement','Interroger le raisonnement','Explorer la même phrase avec les regards de l’artisan, de l’anthropologue et du cartographe.')]
labcards=''.join(f'<a class="lab-card" href="{s}.html#exploration">{icon(s)}<div><h3>{t}</h3><p>{d}</p><span class="text-link">Ouvrir l’exploration ↗</span></div></a>' for s,t,d in labdescs)
home=f'''<main id="contenu"><div class="wrap"><section class="hero"><div><span class="eyebrow">Christophe Gauld · Une invitation à comprendre</span><h1>Classer<br>la folie <em>?</em></h1><div class="hero-subtitle">Une philosophie de la psychiatrie<br>pour le soin</div><p>Nommer une souffrance permet de la reconnaître et d’organiser des soins. Mais que dit un diagnostic de l’expérience d’une personne, de son histoire et de son monde ? Ce parcours explore les questions du livre, puis les modèles qui ouvrent d’autres façons de comprendre.</p><div class="actions"><a class="button" href="ecouter.html">Commencer la découverte <span aria-hidden="true">→</span></a><a class="text-link" href="explorer.html">Choisir une question</a></div></div>{atlas}</section></div><section class="section"><div class="wrap intro-grid"><div><span class="eyebrow">Entrer dans le sujet</span><h2>Des mots de la clinique<br>aux questions philosophiques</h2></div><div class="reading"><p>Qu’est-ce qu’un symptôme ? Pourquoi plusieurs classifications peuvent-elles coexister ? Comment distinguer une explication, une preuve et une promesse ? La philosophie de la psychiatrie aide à formuler ces questions, à examiner les réponses et à comprendre leurs conséquences pour le soin.</p><p>Vous pouvez suivre le parcours depuis le début ou entrer par une question. Les notions sont définies au fil des textes ; les citations vous ramènent aux pages de l’ouvrage. Aucun prérequis en philosophie ou en mathématiques n’est nécessaire.</p><a class="text-link" href="parcours.html">Trouver son chemin dans le site →</a></div></div></section><section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">Première traversée · Les fondements</span><h2>Comprendre ce que l’on fait<br>quand on nomme et que l’on soigne</h2></div><p>Partir de l’expérience, examiner les catégories, faire dialoguer les modèles et questionner les promesses. Quatre étapes pour aborder les ouvertures du livre.</p></div><div class="journey-list">{''.join(row(l,i) for i,l in enumerate(LESSONS[:4]))}</div></div></section><section class="section green-section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">Deuxième traversée · Les ouvertures</span><h2>Quatre manières d’explorer<br>la complexité clinique</h2></div><p>Des textes pour comprendre les modèles, puis des explorations visuelles pour examiner ce qu’ils montrent et les questions qu’ils laissent ouvertes.</p></div><div class="lab-grid">{labcards}</div><a class="text-link" href="mondes.html" style="display:inline-block;margin-top:26px">Prolonger vers les mondes sociaux, culturels et vivants →</a></div></section><section class="section"><div class="wrap">{quote('Le propos général de cet ouvrage n’est donc pas de construire une théorie close, mais d’accueillir une multiplicité de positionnements, d’hypothèses et de postures épistémiques, chacune invitant à penser autrement la complexité du soin et du psychisme.',11,True)}</div></section><section class="section"><div class="wrap"><div class="section-heading"><div><span class="eyebrow">Selon votre point de départ</span><h2>Un même livre, plusieurs chemins</h2></div></div><div class="path-grid"><div class="path-card"><h3>En formation</h3><p>Acquérir le vocabulaire, interroger les catégories et relier les modèles à la rencontre clinique.</p><a class="text-link" href="parcours.html#formation">Le parcours des internes →</a></div><div class="path-card"><h3>Dans la pratique du soin</h3><p>Revenir à la plainte, au contexte et aux interactions pour réfléchir à ce que les outils peuvent apporter.</p><a class="text-link" href="parcours.html#soin">Le parcours des professionnels →</a></div><div class="path-card"><h3>Pour écrire et transmettre</h3><p>Distinguer hypothèses, résultats et promesses, puis trouver les mots pour en parler avec précision.</p><a class="text-link" href="parcours.html#journalisme">Le parcours des journalistes →</a></div></div></div></section><section class="section"><div class="wrap book-strip">{bookobject()}<div><span class="eyebrow">Le livre à l’origine du parcours</span><h2>Prolonger la lecture</h2><p><i>Classer la folie ? Une philosophie de la psychiatrie pour le soin</i>, de Christophe Gauld, avec une préface de Bruno Falissard. Publié chez Hermann en 2026.</p><p>Le site propose une traversée pédagogique de ses idées. L’ouvrage développe les arguments, les débats et les références dans toute leur ampleur.</p><div class="actions"><a class="button secondary" href="livre.html">Découvrir l’ouvrage →</a><a class="text-link" href="sources.html">Sources et lectures</a></div></div></div></section></main>'''
page('index.html','Découvrir la philosophie de la psychiatrie','Un parcours accessible à partir du livre de Christophe Gauld : symptômes, classifications, systèmes dynamiques, réseaux, codage prédictif et IA.',home)
search=[]
# Link selected concepts on first relevant occurrence, preserving the explicit links above.
AUTO={'temps':{'attracteur':'attracteur','multistabilité':'multistabilite','hystérésis':'hysteresis','données longitudinales':'longitudinal'},'reseaux':{'variable latente':'variable-latente','nomothétique':'nomothetique','idiographique':'idiographique','PECAN':'pecan','centralité':'centralite','anhédonie':'anhedonie'},'prediction':{'codage prédictif':'codage-predictif','bayésiennes':'bayesien','erreur de prédiction':'erreur-prediction','inférence active':'inference-active','intéroception':'interoception'},'raisonnement':{'heuristiques':'heuristique','granularité':'granularite','jumeau numérique':'jumeau'}}
for i,l in enumerate(LESSONS):
 sections=[]; toc=[]; auto=dict(AUTO.get(l['slug'],{})); raw=[]
 for sec in l['sections']:
  if 'title' in sec:
   id=slug(sec['title']);toc.append((id,sec['title']))
   paragraphs=[]
   for para in sec['paragraphs']:
    raw.append(para)
    for word,termid in list(auto.items()):
     pat=re.compile(r'(?<!\w)'+re.escape(word)+r'(?!\w)',re.I)
     if pat.search(para):
      para=pat.sub(lambda m:'[['+termid+'|'+m[0]+']]',para,count=1);del auto[word]
    paragraphs.append('<p>'+text(para)+'</p>')
   sections.append(f'<section class="article-section" id="{id}"><h2>{e(sec["title"])}</h2>'+''.join(paragraphs)+'</section>')
  elif 'quote' in sec: sections.append(quote(sec['quote'],sec['page']))
  elif 'note' in sec: sections.append(f'<aside class="note"><strong>{e(sec["note"])}</strong>{text(sec["text"])}</aside>')
  elif 'lab' in sec: sections.append(LABS[sec['lab']]);toc.append(('exploration','L’exploration interactive'))
 words=len(re.findall(r'\w+',' '.join(raw)));mins=math.ceil(words/190)
 l['minutes']=mins;l['words']=words
 aside='<div class="aside-title">La traversée</div>'+''.join(f'<a href="{m["slug"]}.html"'+(' aria-current="page"' if m['slug']==l['slug'] else '')+f'>{j+1:02} · {e(m["short"])}</a>' for j,m in enumerate(LESSONS))
 toc_html=''.join(f'<a href="#{id}">{e(t)}</a>' for id,t in toc)
 prev=LESSONS[i-1] if i else None; nxt=LESSONS[i+1] if i<len(LESSONS)-1 else None
 prev_html=f'<a href="{prev["slug"]}.html"><span>← Étape précédente</span>{e(prev["short"])}</a>' if prev else '<a href="parcours.html"><span>← Choisir son chemin</span>Les parcours</a>'
 next_html=f'<a href="{nxt["slug"]}.html"><span>Étape suivante →</span>{e(nxt["short"])}</a>' if nxt else '<a href="explorer.html"><span>Poursuivre →</span>Revenir aux questions</a>'
 body=f'''<main id="contenu" data-article="{l['slug']}"><div class="wrap"><header class="page-heading"><div class="breadcrumb"><a href="explorer.html">Explorer</a> / Étape {i+1:02}</div><span class="eyebrow">{e(l['kicker'])}</span><h1>{e(l['title'])}</h1><div class="article-meta"><span class="pill">{'Les fondements' if l['group']=='fondements' else 'Les ouvertures'}</span><span>{e(l['chapter'])} · p. {l['pages']}</span><span class="estimate">{mins} min de lecture{' + exploration' if any('lab' in s for s in l['sections']) else ''}</span></div></header><div class="article-layout"><aside class="article-aside" aria-label="Navigation dans le parcours">{aside}<div class="toc"><div class="aside-title">Dans cette page</div>{toc_html}</div></aside><article class="reading"><details class="mobile-toc"><summary>Dans cette page</summary>{toc_html}</details><p class="article-intro">{e(l['intro'])}</p>{''.join(sections)}<aside class="question-box"><h3>Une question à emporter</h3><p>{e(l['question'])}</p></aside><div class="source-note"><strong>Retrouver ces idées dans l’ouvrage</strong><br>Christophe Gauld, <i>Classer la folie ? Une philosophie de la psychiatrie pour le soin</i>, Hermann, 2026. {e(l['chapter'])}, p. {l['pages']}. Les textes sont des reformulations pédagogiques ; les citations sont indiquées entre guillemets et paginées. <a href="sources.html#{l['slug']}">Voir les sources et les choix d’adaptation</a></div><button class="complete-button" data-complete="{l['slug']}" aria-pressed="false">Marquer cette étape comme lue</button><nav class="next-prev" aria-label="Étapes précédente et suivante">{prev_html}{next_html}</nav><a class="back-to-top" href="#contenu">Revenir en haut ↑</a></article></div></div></main>'''
 page(l['slug']+'.html',l['title'],l['intro'],body,'Explorer',True)
 search.append(dict(title=l['title'],kind='Étape '+str(i+1),url=l['slug']+'.html',text=l['intro']+' '+' '.join(raw),excerpt=l['intro']))
# Explorer
rows=''.join(row(l,i) for i,l in enumerate(LESSONS))
body=f'''<main id="contenu" class="wrap"><header class="page-heading"><span class="eyebrow">Neuf questions pour entrer dans le livre</span><h1>Explorer les idées</h1><p class="lead">Suivez la traversée ou choisissez le point qui vous intéresse. Chaque étape peut se lire seule et vous propose des liens pour continuer.</p></header><div class="explore-filters" role="group" aria-label="Filtrer les étapes"><button class="filter-button" data-filter="all" aria-pressed="true">Toute la traversée</button><button class="filter-button" data-filter="fondements" aria-pressed="false">Les fondements</button><button class="filter-button" data-filter="ouvertures" aria-pressed="false">Les ouvertures</button></div><p id="reading-counter" class="reading-counter">Votre progression reste enregistrée sur cet appareil.</p><div class="journey-list">{rows}</div><button class="reset-progress" id="reset-progress">Effacer ma progression sur cet appareil</button><div class="section"><h2>Une notion vous manque ?</h2><p style="margin:20px 0">Le lexique rassemble {len(GLOSSARY)} définitions avec des renvois vers les pages où elles sont développées.</p><a class="button secondary" href="lexique.html">Ouvrir le lexique →</a></div></main>'''
page('explorer.html','Explorer les idées','Neuf étapes pour découvrir les questions et les ouvertures de Classer la folie ?, avec progression de lecture.',body,'Explorer')
PATHS=[('decouverte','Découvrir depuis le début','Pour toute personne qui aborde ces sujets sans formation préalable. Commencez par l’expérience vécue, puis prenez le temps d’examiner ce que font les catégories et les modèles.',['ecouter','classer','pluralisme','promesses','temps','reseaux','prediction','raisonnement','mondes'],'À chaque étape, demandez-vous quelle question est posée et ce que le modèle laisse de côté.'),('formation','Pour les internes','Un chemin pour relier le vocabulaire philosophique à la pratique clinique et aborder les modèles de la partie II. Les explorations ne demandent pas de prérequis mathématiques.',['ecouter','classer','pluralisme','temps','reseaux','prediction','raisonnement'],'En groupe, choisissez une situation fictive et comparez ce que chaque perspective vous conduit à demander. Évitez de traiter les modèles comme des recettes de soin.'),('soin','Pour les professionnels de santé','Un parcours centré sur la description, les interactions, le contexte et la place du raisonnement. Les étapes sur les classifications et le pluralisme restent accessibles à tout moment.',['ecouter','temps','reseaux','raisonnement','mondes'],'Quelles informations viennent du récit, lesquelles des mesures, lesquelles de vos hypothèses ? Comment la personne peut-elle discuter cette compréhension ?'),('journalisme','Pour les journalistes','Un chemin pour décrire les modèles et les innovations sans confondre les niveaux de preuve. Il conduit des catégories aux promesses, puis aux usages possibles et aux limites des outils.',['classer','promesses','reseaux','prediction','raisonnement','mondes'],'Pour une annonce scientifique, distinguez ce qui est décrit, ce qui est supposé, ce qui a été mesuré et ce qui reste promis. La page Sources permet de retrouver les passages du livre.')]
blocks=[]
for id,title,desc,steps,question in PATHS:
 est=sum(next(l['minutes'] for l in LESSONS if l['slug']==s) for s in steps)
 lis=''.join(f'<li><span>{j+1:02}</span><a href="{s}.html">{e(next(l["short"] for l in LESSONS if l["slug"]==s))}</a></li>' for j,s in enumerate(steps))
 blocks.append(f'<section class="path-panel" id="{id}"><div><span class="eyebrow">Environ {est} min de lecture</span><h2>{title}</h2></div><div><p>{desc}</p><ol class="path-steps">{lis}</ol><aside class="note"><strong>Pour accompagner la lecture</strong>{question}</aside><a class="button" href="{steps[0]}.html">Commencer ce parcours →</a></div></section>')
body='<main id="contenu" class="wrap"><header class="page-heading"><span class="eyebrow">Choisir son point de départ</span><h1>Des chemins de lecture</h1><p class="lead">Les mêmes questions peuvent être abordées depuis la formation, la pratique du soin ou le travail d’information. Ces parcours proposent un ordre ; vous restez libre d’en sortir et d’y revenir.</p></header>'+''.join(blocks)+'</main>'
page('parcours.html','Des chemins de lecture','Quatre parcours accessibles : découverte, internes, professionnels de santé et journalistes.',body,'Parcours')
# Glossary
GLOSSARY.sort(key=lambda g:unicodedata.normalize('NFKD',g['term']).casefold())
definitions=''.join(f'<section class="definition" id="{g["id"]}" data-definition="{e(g["term"],quote=True)}"><h2>{e(g["term"])}</h2><p>{e(g["definition"])}</p><a class="see" href="{g["lesson"]}.html">Approfondir dans le parcours →</a><small class="muted">Pages d’appui dans le livre : {g["pages"]}</small></section>' for g in GLOSSARY)
body=f'''<main id="contenu" class="wrap"><header class="page-heading"><span class="eyebrow">Les mots, pas à pas</span><h1>Un lexique pour entrer<br>dans les concepts</h1><p class="lead">{len(GLOSSARY)} définitions pour accompagner la lecture. Elles proposent un premier repère ; les pages du parcours développent les nuances et les discussions.</p></header><div class="glossary-toolbar"><label for="glossary-search" class="screenreader">Filtrer les définitions</label><input class="search-field" type="search" id="glossary-search" placeholder="Chercher un mot ou une idée…"><span class="small muted" id="glossary-count" aria-live="polite">{len(GLOSSARY)} notions</span></div><div class="glossary-grid">{definitions}</div><p id="glossary-empty" class="empty-state" hidden>Aucune définition ne correspond. Essayez un autre mot ou la recherche générale du site.</p><div style="padding-bottom:50px"></div></main>'''
page('lexique.html','Le lexique','Définitions accessibles des notions de philosophie de la psychiatrie, de complexité et de raisonnement clinique.',body,'Lexique')
